create table public.inventory_levels (store_id uuid not null, location_id uuid not null, variant_id uuid not null, on_hand integer not null default 0 check(on_hand >= 0), reserved integer not null default 0 check(reserved >= 0 and reserved <= on_hand), updated_at timestamptz not null default now(), primary key(location_id,variant_id), foreign key(store_id,location_id) references public.inventory_locations(store_id,id) on delete cascade, foreign key(store_id,variant_id) references public.product_variants(store_id,id) on delete cascade);
